protected ProdTable createProdTable(ReqTrans _reqTrans, ReqPO _reqPO, ProdBOM _prodBOMParent)
{
    ProdTable prodTable;

    prodTable = next createProdTable(_reqTrans,_reqPO, _prodBOMParent);

    if (_reqPO.AVARUMSalesId)
    {
        // Values for the waste management module
        prodTable.AVARUMSalesRefId = _reqPO.AVARUMSalesId;
        prodTable.AVARUMSalesRefTransId = _reqPO.AVARUMInventTransId;
    }

    return prodTable;
}
